import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, uniform, mix } from 'three/tsl';

export default function createNode(config, ctx) {
  const { PlaneGeometry, Mesh, Group } = ctx.THREE;

  // Create group to hold the plane
  const group = new Group();
  group.position.set(-3.2, -0.3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Create plane geometry (standard journal card aspect ratio)
  const geometry = new PlaneGeometry(2.0, 1.25, 1, 1);

  // Create material with texture
  const material = new MeshBasicNodeMaterial({
    toneMapped: true,
  });

  // Load and apply the image texture
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  texturePromise.then((texture) => {
    // Set UV as the base color node
    material.colorNode = uv();
    material.map = texture;
    material.needsUpdate = true;
  });

  // Create mesh and add to group
  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Setup cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (mesh.material.map) {
      mesh.material.map.dispose();
    }
  };

  group.userData.handlers = {};

  return group;
}
